   446  int zmq::zmtp_engine_t::process_routing_id_msg (msg_t *msg_)
   447  {
   448      if (_options.recv_routing_id) {
   449          msg_->set_flags (msg_t::routing_id);
   450          const int rc = session ()->push_msg (msg_);
   451          errno_assert (rc == 0);
   452      } else {
   453          int rc = msg_->close ();
   454          errno_assert (rc == 0);
   455          rc = msg_->init ();
   456          errno_assert (rc == 0);
   457      }
   458
   459      if (_subscription_required) {
   460          msg_t subscription;
   461
   462          //  Inject the subscription message, so that also
   463          //  ZMQ 2.x peers receive published messages.
   464          int rc = subscription.init_size (1);
   465          errno_assert (rc == 0);
   466          *static_cast<unsigned char *> (subscription.data ()) = 1;
   467          rc = session ()->push_msg (&subscription);
   468          errno_assert (rc == 0);
   469      }
   470
   471      _process_msg = &zmtp_engine_t::push_msg_to_session;
   472
   473      return 0;
   474  }
