   265  void zmq::session_base_t::pipe_terminated (pipe_t *pipe_)
   266  {
   267      // Drop the reference to the deallocated pipe if required.
   268      zmq_assert (pipe_ == _pipe || pipe_ == _zap_pipe
   269                  || _terminating_pipes.count (pipe_) == 1);
   270
   271      if (pipe_ == _pipe) {
   272          // If this is our current pipe, remove it
   273          _pipe = NULL;
   274          if (_has_linger_timer) {
   275              cancel_timer (linger_timer_id);
   276              _has_linger_timer = false;
   277          }
   278      } else if (pipe_ == _zap_pipe)
   279          _zap_pipe = NULL;
   280      else
   281          // Remove the pipe from the detached pipes set
   282          _terminating_pipes.erase (pipe_);
   283
   284      if (!is_terminating () && options.raw_socket) {
   285          if (_engine) {
   286              _engine->terminate ();
   287              _engine = NULL;
   288          }
   289          terminate ();
   290      }
   291
   292      //  If we are waiting for pending messages to be sent, at this point
   293      //  we are sure that there will be no more messages and we can proceed
   294      //  with termination safely.
   295      if (_pending && !_pipe && !_zap_pipe && _terminating_pipes.empty ()) {
   296          _pending = false;
   297          own_t::process_term (0);
   298      }
   299  }
